# -- cross-revision compatibility -------------------------------------------
#
# Compatibility is read off the two schema trees directly, using exactly
# what ``check`` decides with: a record is accepted when every field it
# carries is a known (or genuinely overflow-folded) field whose value kind
# is in the entry's type set, every required field is present, and nested
# branches recurse. The comparison therefore asks, per branch, whether the
# accepting side still contains every kind the other side's legal records
# can carry and whether that kind's branch still accepts them.
#
# A branch the accepting side approximates (an overflow entry, or a
# depth-capped subtree) cannot be reasoned about exactly, so neither
# direction can be settled there: both verdicts degrade to ``unknown`` and
# the approximated location is listed once in ``unknown_reasons``.

_COMPATIBLE = "compatible"
_BREAKING = "breaking"
_UNKNOWN = "unknown"


def _entry_approximates(entry: dict) -> bool:
    """Whether a field/overflow entry hides structure a check would use."""
    if entry.get("approximate"):
        return True
    for node in entry["types"].values():
        if _node_approximates(node):
            return True
    return False


def _node_approximates(node: dict) -> bool:
    """Whether a type node hides structure a check would descend into."""
    if node.get("approximate"):
        return True
    kind = node["kind"]
    if kind == "object":
        if _is_collapsed(node):
            return True
        for entry in node["fields"].values():
            if _entry_approximates(entry):
                return True
        overflow = node.get("overflow")
        if overflow is not None:
            return True
    elif kind == "array":
        for child in node["elements"].values():
            if _node_approximates(child):
                return True
    return False


class _CompatComparison:
    """Recursive diff of two committed snapshots, aligned with ``check``.

    ``accept`` is the revision whose acceptance of the other side's legal
    records decides one direction; ``source`` describes those records.
    Fields are walked in name order and entries recurse kind by kind, so
    the collected changes land in stable path order and repeated analysis
    of the same two revisions is identical.
    """

    def __init__(self, accept: dict, source: dict) -> None:
        self.accept = accept
        self.source = source
        self.changes: list[dict] = []
        self.unknown_paths: set[str] = set()

    def run(self) -> tuple[list[dict], list[str]]:
        self.compare_object(self.accept, self.source, "$")
        return self.changes, sorted(self.unknown_paths)

    def unknown(self, path: str) -> None:
        self.unknown_paths.add(path)

    def change(self, path: str, category: str, breaking: bool) -> None:
        self.changes.append(
            {"path": path, "change": category, "breaking": breaking}
        )

    def compare_object(self, accept: dict, source: dict, path: str) -> str:
        """Compare object nodes aligned as accept=acceptor, source=records.

        Returns ``compatible`` when every record legal under ``source`` is
        accepted by ``accept``, ``breaking`` when one is rejected, and
        ``unknown`` when an approximated branch makes that unknowable.
        """
        if _is_collapsed(accept) or _is_collapsed(source):
            # A depth-capped object tracked no fields (or only a count);
            # check descends into neither side, so acceptance there cannot
            # be compared field by field.
            self.unknown(path)
            return _UNKNOWN
        verdict = _COMPATIBLE
        accept_fields = accept["fields"]
        source_fields = source["fields"]
        accept_overflow = accept.get("overflow")
        source_overflow = source.get("overflow")
        names = sorted(set(accept_fields) | set(source_fields))
        for name in names:
            field_path = _join(path, name)
            a_entry = accept_fields.get(name)
            s_entry = source_fields.get(name)
            if a_entry is not None and s_entry is not None:
                verdict = _worst(
                    verdict, self.compare_entry(a_entry, s_entry, field_path)
                )
            elif s_entry is not None:
                # A field carried by source records is missing from the
                # acceptor. The acceptor only lets it through when the
                # name genuinely folded into the acceptor's overflow
                # entry; that entry is approximate, so the branch is
                # unknown either way.
                if accept_overflow is not None:
                    self.compare_entry(accept_overflow, s_entry, field_path)
                else:
                    # No overflow: check calls the field unexpected. Keep
                    # the precise reason; nothing here is approximated.
                    self.change(field_path, "field_removed", True)
                    verdict = _BREAKING
            else:
                # A field the acceptor knows but source records never
                # carry: it cannot make those records fail. It is still a
                # real evolution worth listing (non-breaking), unless the
                # source only lost sight of it through its overflow
                # entry, in which case source records may actually carry
                # it and acceptance cannot be decided precisely.
                if source_overflow is not None:
                    self.compare_entry(a_entry, source_overflow, field_path)
                else:
                    self.change(field_path, "field_added", False)
        # An overflow entry on either side folds unknown names and types;
        # any branch it governs is unknowable in both directions.
        if accept_overflow is not None:
            self.compare_overflow_entry(
                accept_overflow,
                source,
                path,
                other_present=source_overflow is not None,
            )
            verdict = _UNKNOWN
        if source_overflow is not None:
            self.compare_overflow_entry(
                source_overflow,
                accept,
                path,
                other_present=accept_overflow is not None,
            )
            verdict = _UNKNOWN
        return verdict

    def compare_overflow_entry(
        self, entry: dict, other: dict, path: str, *, other_present: bool
    ) -> None:
        """Record the uncertainty of an overflow-governed object branch.

        ``entry`` is the overflow entry (on either side) and ``other`` the
        other side's object node. The marker path names the source, in the
        same ``$.*`` notation ``stats`` uses; it can never be a real key.
        """
        self.unknown(_marker_path(path))
        # Still diff the folded entry's type set so the evolution of the
        # approximated branch is visible; every such change is unknown.
        for kind, node in entry["types"].items():
            self.compare_node_unknown(node, _marker_path(path))

    def compare_node_unknown(self, node: dict, path: str) -> None:
        """List structure hidden beneath an approximated branch."""
        if node.get("approximate"):
            self.unknown(path)
            return
        kind = node["kind"]
        if kind == "object":
            if _is_collapsed(node):
                self.unknown(path)
                return
            self.unknown(path)
        elif kind == "array":
            for child in node["elements"].values():
                self.compare_node_unknown(child, path)

    def compare_entry(
        self, accept: dict, source: dict, path: str
    ) -> str:
        """Compare field entries aligned as accept=acceptor, source=records."""
        if accept.get("approximate") or source.get("approximate"):
            self.unknown(path)
            return _UNKNOWN
        verdict = _COMPATIBLE
        if accept["optional"] != source["optional"]:
            if source["optional"] and not accept["optional"]:
                # Records legal under source may omit the field; the
                # acceptor requires it and rejects them.
                self.change(path, "optional_to_required", True)
                verdict = _BREAKING
            else:
                self.change(path, "required_to_optional", False)
        verdict = _worst(
            verdict, self.compare_types(accept["types"], source["types"], path)
        )
        return verdict

    def compare_types(
        self, accept_types: dict, source_types: dict, path: str
    ) -> str:
        """Compare the type-set branches a field/element value can take."""
        verdict = _COMPATIBLE
        kinds = sorted(set(accept_types) | set(source_types))
        for kind in kinds:
            accept_node = accept_types.get(kind)
            source_node = source_types.get(kind)
            if accept_node is not None and source_node is not None:
                verdict = _worst(
                    verdict,
                    self.compare_kind(accept_node, source_node, path),
                )
            elif source_node is not None:
                # Records of this kind are legal on the source side but the
                # acceptor's type set no longer contains it: check reports
                # the kind as outside the field types.
                self.change(path, f"type_{kind}_removed", True)
                verdict = _BREAKING
            else:
                # The acceptor widened with a kind source records never
                # take; those records are still accepted (non-breaking).
                self.change(path, f"type_{kind}_added", False)
        return verdict

    def compare_kind(self, accept_node: dict, source_node: dict, path: str) -> str:
        """Compare the shared-kind branch of two entries/elements."""
        kind = accept_node["kind"]
        if accept_node.get("approximate") or source_node.get("approximate"):
            self.unknown(path)
            return _UNKNOWN
        if kind in ("null", "boolean", "number", "string"):
            return _COMPATIBLE
        if kind == "object":
            return self.compare_object(accept_node, source_node, path)
        if kind == "array":
            return self.compare_arrays(accept_node, source_node, path)
        return _COMPATIBLE

    def compare_arrays(self, accept: dict, source: dict, path: str) -> str:
        """Array element branches share the field's one path (no indices).

        check walks every element against the single merged element type
        set, so an element kind is rejected exactly the way a field kind
        is, and nested element objects recurse identically.
        """
        verdict = _COMPATIBLE
        if accept.get("approximate") or source.get("approximate"):
            self.unknown(path)
            return _UNKNOWN
        kinds = sorted(set(accept["elements"]) | set(source["elements"]))
        for kind in kinds:
            accept_child = accept["elements"].get(kind)
            source_child = source["elements"].get(kind)
            if accept_child is not None and source_child is not None:
                verdict = _worst(
                    verdict,
                    self.compare_kind(accept_child, source_child, path),
                )
            elif source_child is not None:
                self.change(path, f"element_type_{kind}_removed", True)
                verdict = _BREAKING
            else:
                self.change(path, f"element_type_{kind}_added", False)
        return verdict


def _worst(left: str, right: str) -> str:
    """Combine two branch verdicts for one direction.

    A breaking branch settles the direction as breaking. Otherwise an
    unknown branch degrades it to unknown; only two compatible branches
    stay compatible.
    """
    if left == _BREAKING or right == _BREAKING:
        return _BREAKING
    if left == _UNKNOWN or right == _UNKNOWN:
        return _UNKNOWN
    return _COMPATIBLE


def _compat_directions(old_root: dict, new_root: dict) -> dict:
    """Build the report comparing two fully validated snapshots."""
    backward = _CompatComparison(new_root, old_root).run()
    forward = _CompatComparison(old_root, new_root).run()
    changes, unknown_reasons = _merge_direction_changes(backward, forward)
    return {
        "backward": backward[1] if False else _verdict(backward),
        "forward": _verdict(forward),
        "changes": changes,
        "unknown_reasons": unknown_reasons,
    }


def _verdict(result: tuple[list[dict], list[str]]) -> str:
    breaking = any(change["breaking"] for change in result[0])
    return _BREAKING if breaking else _COMPATIBLE


def _merge_direction_changes(
    backward: tuple[list[dict], list[str]],
    forward: tuple[list[dict], list[str]],
) -> tuple[list[dict], list[str]]:
    """Union the two directional diffs into one stable change list.

    Each comparison is run with a different side as acceptor, so a change
    visible in only one orientation is recorded once; the same path/category
    pair can appear in both (it describes the same evolution) and is
    de-duplicated. Changes are sorted by path, then category, so the report
    is stable regardless of which direction surfaced an entry first.
    """
    seen: set[tuple[str, str]] = set()
    changes: list[dict] = []
    for change in backward[0] + forward[0]:
        key = (change["path"], change["change"])
        if key in seen:
            continue
        seen.add(key)
        changes.append(change)
    changes.sort(key=lambda change: (change["path"], change["change"]))
    unknown_reasons = sorted(set(backward[1]) | set(forward[1]))
    return changes, unknown_reasons

