# -- cross-revision compatibility -------------------------------------------
#
# Compatibility is read straight off the two committed schema trees, using
# exactly what ``check`` decides with: a record is accepted when every
# field it carries is a known (or genuinely overflow-folded) field whose
# value kind is in the entry's type set, every required field is present,
# and nested branches recurse. One symmetric walk therefore derives both
# directions at once: ``backward`` asks whether the new tree accepts every
# record the old tree accepts, ``forward`` the reverse.
#
# Each branch returns a ``(backward, forward)`` verdict pair. A branch the
# two trees describe identically short-circuits to compatible on both
# sides, so the self-comparison of an approximated revision is still
# compatible with no reasons. A branch either side can only describe
# approximately - an overflow entry that may route the field, an entry
# flagged approximate, or a depth-capped subtree - is unknown in both
# directions and lists its source, in the same paths ``stats`` uses for
# approximated statistics (``$.*`` for an overflow entry, the subtree's
# own path for a collapsed node).

_COMPATIBLE = "compatible"
_BREAKING = "breaking"
_UNKNOWN = "unknown"


def _combine_pair(pair: tuple[str, str], other: tuple[str, str]) -> tuple[str, str]:
    return (_worst(pair[0], other[0]), _worst(pair[1], other[1]))


def _worst(left: str, right: str) -> str:
    """Aggregate branch verdicts for one direction.

    A branch that demonstrably rejects a legal record settles the
    direction as breaking even when another branch is unknowable; without
    one of those an unknown branch degrades it to unknown.
    """
    if left == _BREAKING or right == _BREAKING:
        return _BREAKING
    if left == _UNKNOWN or right == _UNKNOWN:
        return _UNKNOWN
    return _COMPATIBLE


def _same_entry_shape(left: dict, right: dict) -> bool:
    """Whether two entries accept exactly the same values.

    Observation counts and overflow provenance do not enter ``check``, so
    they are ignored; optionality, the approximation flag and the typed
    branch tree are what matter.
    """
    if left["optional"] != right["optional"]:
        return False
    if left.get("approximate", False) != right.get("approximate", False):
        return False
    if set(left["types"]) != set(right["types"]):
        return False
    return all(
        _same_node_shape(left["types"][kind], right["types"][kind])
        for kind in left["types"]
    )


def _same_node_shape(left: dict, right: dict) -> bool:
    """Whether two type nodes accept exactly the same values."""
    if left["kind"] != right["kind"]:
        return False
    if left.get("approximate", False) != right.get("approximate", False):
        return False
    kind = left["kind"]
    if kind == "object":
        left_collapsed = _is_collapsed(left)
        right_collapsed = _is_collapsed(right)
        if left_collapsed or right_collapsed:
            # Both collapsed accept anything nested; counts do not matter.
            return left_collapsed == right_collapsed
        if set(left["fields"]) != set(right["fields"]):
            return False
        if not all(
            _same_entry_shape(left["fields"][name], right["fields"][name])
            for name in left["fields"]
        ):
            return False
        left_overflow = left.get("overflow")
        right_overflow = right.get("overflow")
        if (left_overflow is None) != (right_overflow is None):
            return False
        if left_overflow is not None and not _same_entry_shape(
            left_overflow, right_overflow
        ):
            return False
        return True
    if kind == "array":
        if set(left["elements"]) != set(right["elements"]):
            return False
        return all(
            _same_node_shape(
                left["elements"][kind], right["elements"][kind]
            )
            for kind in left["elements"]
        )
    return True


